import{_ as o,a0 as l,w as p,s as d,ao as r,I as t,x as i,a1 as s,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"优化 MySQL： 3 个简单的小调整 | LCTT x X-CMD","titleTemplate":false,"description":"优化 MySQL： 3 个简单的小调整 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"优化 MySQL： 3 个简单的小调整 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"优化 MySQL： 3 个简单的小调整 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180202 Tuning MySQL 3 Simple Tweaks","title":"优化 MySQL： 3 个简单的小调整","tag":"201802","desc":""},"relativePath":"201802/20180202 Tuning MySQL 3 Simple Tweaks.md","filePath":"[post].md"}'),h={name:"201802/20180202 Tuning MySQL 3 Simple Tweaks.md"};function b(u,e,m,g,f,c){const n=l("Link");return p(),d("div",null,[e[13]||(e[13]=r('<h1 id="优化-mysql-3-个简单的小调整" tabindex="-1">优化 MySQL： 3 个简单的小调整 <a class="header-anchor" href="#优化-mysql-3-个简单的小调整" aria-label="Permalink to “优化 MySQL： 3 个简单的小调整”">​</a></h1><p>如果你不改变 MySQL 的缺省配置，你的服务器的性能就像下图的坏在一档的法拉利一样 “虎落平阳被犬欺” …</p><p><img src="https://cdn-images-1.medium.com/max/1000/1*b7M28XbrOc4FF3tJP-vvyg.png" alt=""></p><p>我并不期望成为一个专家级的 DBA，但是，在我优化 MySQL 时，我推崇 80/20 原则，明确说就是通过简单的调整一些配置，你可以压榨出高达 80% 的性能提升。尤其是在服务器资源越来越便宜的当下。</p><h3 id="警告" tabindex="-1">警告 <a class="header-anchor" href="#警告" aria-label="Permalink to “警告”">​</a></h3><ol><li>没有两个数据库或者应用程序是完全相同的。这里假设我们要调整的数据库是为一个“典型”的 Web 网站服务的，优先考虑的是快速查询、良好的用户体验以及处理大量的流量。</li><li>在你对服务器进行优化之前，请做好数据库备份！</li></ol><h3 id="_1、-使用-innodb-存储引擎" tabindex="-1">1、 使用 InnoDB 存储引擎 <a class="header-anchor" href="#_1、-使用-innodb-存储引擎" aria-label="Permalink to “1、 使用 InnoDB 存储引擎”">​</a></h3><p>如果你还在使用 MyISAM 存储引擎，那么是时候转换到 InnoDB 了。有很多的理由都表明 InnoDB 比 MyISAM 更有优势，如果你关注性能，那么，我们来看一下它们是如何利用物理内存的：</p><ul><li>MyISAM：仅在内存中保存索引。</li><li>InnoDB：在内存中保存索引<strong>和</strong>数据。</li></ul><p>结论：保存在内存的内容访问速度要比磁盘上的更快。</p><p>下面是如何在你的表上去转换存储引擎的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE table_name ENGINE=InnoDB;</span></span></code></pre></div><p><em>注意：你已经创建了所有合适的索引，对吗？为了更好的性能，创建索引永远是第一优先考虑的事情。</em></p><h3 id="_2、-让-innodb-使用所有的内存" tabindex="-1">2、 让 InnoDB 使用所有的内存 <a class="header-anchor" href="#_2、-让-innodb-使用所有的内存" aria-label="Permalink to “2、 让 InnoDB 使用所有的内存”">​</a></h3><p>你可以在 <code>my.cnf</code> 文件中编辑你的 MySQL 配置。使用 <code>innodb_buffer_pool_size</code> 参数去配置在你的服务器上允许 InnoDB 使用物理内存数量。</p><p>对此（假设你的服务器_仅仅_运行 MySQL），公认的“经验法则”是设置为你的服务器物理内存的 80%。在保证操作系统不使用交换分区而正常运行所需要的足够内存之后 ，尽可能多地为 MySQL 分配物理内存。</p><p>因此，如果你的服务器物理内存是 32 GB，可以将那个参数设置为多达 25 GB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>innodb_buffer_pool_size = 25600M</span></span></code></pre></div><p>*注意：（1）如果你的服务器内存较小并且小于 1 GB。为了适用本文的方法，你应该去升级你的服务器。 （2） 如果你的服务器内存特别大，比如，它有 200 GB，那么，根据一般常识，你也没有必要为操作系统保留多达 40 GB 的内存。 *</p><h3 id="_3、-让-innodb-多任务运行" tabindex="-1">3、 让 InnoDB 多任务运行 <a class="header-anchor" href="#_3、-让-innodb-多任务运行" aria-label="Permalink to “3、 让 InnoDB 多任务运行”">​</a></h3><p>如果服务器上的参数 <code>innodb_buffer_pool_size</code> 的配置是大于 1 GB，将根据参数 <code>innodb_buffer_pool_instances</code> 的设置， 将 InnoDB 的缓冲池划分为多个。</p><p>拥有多于一个的缓冲池的好处有：</p><blockquote><p>在多线程同时访问缓冲池时可能会遇到瓶颈。你可以通过启用多缓冲池来最小化这种争用情况：</p></blockquote><p>对于缓冲池数量的官方建议是：</p><blockquote><p>为了实现最佳的效果，要综合考虑 <code>innodb_buffer_pool_instances</code> 和 <code>innodb_buffer_pool_size</code> 的设置，以确保每个实例至少有不小于 1 GB 的缓冲池。</p></blockquote><p>因此，在我们的示例中，将参数 <code>innodb_buffer_pool_size</code> 设置为 25 GB 的拥有 32 GB 物理内存的服务器上。一个合适的设置为 25600M / 24 = 1.06 GB</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>innodb_buffer_pool_instances = 24</span></span></code></pre></div><h3 id="注意" tabindex="-1">注意！ <a class="header-anchor" href="#注意" aria-label="Permalink to “注意！”">​</a></h3><p>在修改了 <code>my.cnf</code> 文件后需要重启 MySQL 才能生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo service mysql restart</span></span></code></pre></div><hr><p>还有更多更科学的方法来优化这些参数，但是这几点可以作为一个通用准则来应用，将使你的 MySQL 服务器性能更好。</p><hr><p>作者简介:</p><p>我喜欢商业技术以及跑车 | 集团 CTO @ Parcel Monkey， Cloud Fulfilment &amp; Kong。</p><hr>',36)),t("p",null,[e[1]||(e[1]=i("via: ",-1)),s(n,{href:"https://medium.com/@richb_/tuning-mysql-3-simple-tweaks-6356768f9b90"},{default:a(()=>[...e[0]||(e[0]=[i("https://medium.com/@richb_/tuning-mysql-3-simple-tweaks-6356768f9b90",-1)])]),_:1})]),t("p",null,[e[5]||(e[5]=i("作者：",-1)),s(n,{href:"https://medium.com/@richb_"},{default:a(()=>[...e[2]||(e[2]=[i("Rich Barrett",-1)])]),_:1}),e[6]||(e[6]=i(" 译者：",-1)),s(n,{href:"https://github.com/qhwdw"},{default:a(()=>[...e[3]||(e[3]=[i("qhwdw",-1)])]),_:1}),e[7]||(e[7]=i(" 校对：",-1)),s(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[i("wxy",-1)])]),_:1})]),t("p",null,[e[10]||(e[10]=i("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[i("LCTT",-1)])]),_:1}),e[11]||(e[11]=i(" 原创编译，",-1)),s(n,{href:"https://linux.cn/"},{default:a(()=>[...e[9]||(e[9]=[i("Linux中国",-1)])]),_:1}),e[12]||(e[12]=i(" 荣誉推出",-1))])])}const T=o(h,[["render",b]]);export{y as __pageData,T as default};
